"rb_say":{"message0":"dizer %1","tooltip":"Escreve uma nota no registo da execução."},
"rb_score":{"message0":"classificar %1 de 0 a 10 quanto a %2"},
"rb_set_draft":{"message0":"definir o rascunho como %1"},
